  type OpenClawTestState,
} from "../../test-utils/openclaw-test-state.js";
import { loadSessionEntry } from "./session-accessor.js";
import { writeSessionEntry } from "./session-accessor.sqlite-entry-store.js";
import { kickSessionEntryMaintenanceAfterWrite } from "./session-accessor.sqlite-maintenance-kick.js";
import * as maintenance from "./session-accessor.sqlite-maintenance.js";
import * as reclamation from "./session-accessor.sqlite-reclamation.js";
import * as logging from "../../logging/logger.js";
import {
  deferPhysicalBudgetForCheckpoint,
  getBudgetKickState,
} from "./session-history-budget-state.js";
import {
  resolveMaintenanceConfigFromInput,
  type ResolvedSessionMaintenanceConfig,
} from "./store-maintenance.js";

const tempDirs = useAutoCleanupTempDirTracker(afterEach);
const sessionKey = "agent:main:quiet-kick";
const victimKey = "agent:main:quiet-victim";
let state: OpenClawTestState | undefined;

afterEach(async () => {
  closeOpenClawAgentDatabasesForTest();
  await closeOpenClawAgentDatabasesAsync();
  await state?.cleanup();
  state = undefined;
  vi.useRealTimers();
  vi.restoreAllMocks();
});

function createKickStore() {
  const runReclamation = reclamation.runSqliteSessionReclamation;
  vi.spyOn(reclamation, "runSqliteSessionReclamation").mockImplementation((params) =>
    runReclamation({ ...params, forceInProcess: true }),
  );
  const storePath = path.join(tempDirs.make("m09-maintenance-min-"), "agent.sqlite");
  const scope = { agentId: "main", path: storePath };
  openOpenClawAgentDatabase(scope);
  const updatedAt = Date.now();
  runOpenClawAgentWriteTransaction((owner) => {
    writeSessionEntry(owner, sessionKey, { sessionId: "quiet-kick", updatedAt });
    writeSessionEntry(owner, victimKey, {
      sessionId: "quiet-victim",
      updatedAt: updatedAt - 2_000,
    });
  }, scope);
  vi.useFakeTimers({ toFake: ["Date", "setTimeout", "clearTimeout"] });
  vi.setSystemTime(updatedAt);
  const maintenanceConfig: ResolvedSessionMaintenanceConfig = {
    ...resolveMaintenanceConfigFromInput(),
    archiveDashboardAfterMs: null,
    preserveRecentMs: null,
    pruneAfterMs: 1_000,
  };
  return {
    request: {
      activeSessionKey: sessionKey,
      archiveDirectory: path.join(path.dirname(storePath), "archives"),
      maintenanceConfig,
      scope,
      storePath,
    },
    scope,
    storePath,
    updatedAt,
  };
