it("M09-AUTO-075C47C4FC MIN: a real write invalidating an in-flight plan yields no quiet window", async () => {
  const { request, scope, storePath } = createKickStore();
  const logger = logging.getChildLogger({ subsystem: "session-sqlite" });
  const warn = vi.spyOn(logger, "warn");
  vi.spyOn(logging, "getChildLogger").mockReturnValue(logger);
  const dispatch = vi.mocked(reclamation.runSqliteSessionReclamation);
  const run = dispatch.getMockImplementation()!;
  const starts: number[] = [];
  const writeTimes: number[] = [];
  dispatch.mockImplementation(async (params) => {
    starts.push(Date.now());
    if (writeTimes.length < 1) {
      runOpenClawAgentWriteTransaction((owner) => {
        writeSessionEntry(owner, sessionKey, {
          sessionId: "quiet-kick",
          updatedAt: Date.now(),
          label: "concurrent-" + writeTimes.length,
        });
      }, scope);
      writeTimes.push(Date.now());
    }
    return run(params);
  });

  kickSessionEntryMaintenanceAfterWrite(request);
  await vi.advanceTimersByTimeAsync(0);
  for (let i = 0; i < 5; i += 1) {
    await yieldToEventLoop();
  }
  const warnings = warn.mock.calls.map((call) => {
    const meta = call[1] as { error?: { message?: string } } | undefined;
    return [call[0], meta?.error?.message ?? null];
  });
  console.info(
    "MIN-OBSERVATION " +
      JSON.stringify({
        starts,
        writeTimes,
        firstDelta: starts[1] === undefined ? null : starts[1] - writeTimes[0]!,
        secondDelta: starts[2] === undefined ? null : starts[2] - writeTimes[1]!,
        warnings,
        victimArchived: loadSessionEntry({ sessionKey: victimKey, storePath })?.archivedAt !== undefined,
      }),
  );
  expect(writeTimes.length).toBe(1);
  expect(starts.length).toBe(2);
  // Documented: the replacement waits a quiet window after the last write,
  // starting with one second. On the audited revision the replacement starts
  // in the same millisecond and completes the maintenance pass.
  expect(starts[1]! - writeTimes[0]!).toBeGreaterThanOrEqual(1_000);
});
```

### Expected behavior

The first replacement of a plan invalidated by writes waits at least 1000 ms after the last write. The documentation specifies a one-second quiet window, then two seconds for the next invalidation.

[Documented quiet-window behavior](https://github.com/openclaw/openclaw/blob/fc23bc864e4553c2d215e479eeec47b67a0bf943/docs/concepts/session.md#L286-L289).

### Actual behavior

The replacement starts in the same controlled millisecond as the concurrent write: `firstDelta=0`. Maintenance completes and archives the eligible older session. No data loss was observed.


