<details>
<summary>Twilio carrier simulator used for the run</summary>

Install `ws` and `twilio` in a scratch npm project, configure the product webhook plus a fake realtime metrics endpoint, and run this script. Synthetic TLS uses a locally trusted test certificate; the lookup hook maps the synthetic proof hostname to loopback.

```js
import assert from "node:assert/strict";
import { randomBytes } from "node:crypto";
import https from "node:https";
import twilio from "twilio";
import WebSocket from "ws";

const webhookUrl = process.env.TWILIO_WEBHOOK_URL;
const authToken = process.env.TWILIO_AUTH_TOKEN;
const metricsUrl = process.env.FAKE_REALTIME_METRICS_URL;
assert(webhookUrl, "TWILIO_WEBHOOK_URL is required");
assert(authToken, "TWILIO_AUTH_TOKEN is required");
assert(metricsUrl, "FAKE_REALTIME_METRICS_URL is required");

const makeSid = (prefix) => prefix + randomBytes(16).toString("hex");
const accountSid = makeSid("AC");
const matchingCallSid = makeSid("CA");
const mismatchedCallSid = makeSid("CA");
const mismatchSignedCallSid = makeSid("CA");
const matchingStreamSid = makeSid("MZ");
const mismatchStreamSid = makeSid("MZ");
const mediaPayload = Buffer.alloc(160, 0xff).toString("base64");

const now = () => new Date().toISOString();
const redactSid = (value) => value.replace(/^(AC|CA|MZ).+$/, "$1…redacted");
const redactUrl = (value) => value.replace(/\/([0-9a-f-]{36})(?=$|[?#])/, "/<one-time-token>");
const log = (event, details = {}) =>
  console.log(JSON.stringify({ timestamp: now(), event, ...details }));
const loopbackLookup = (_hostname, options, callback) => {
  if (options?.all) {
    callback(null, [{ address: "127.0.0.1", family: 4 }]);
    return;
  }
  callback(null, "127.0.0.1", 4);
};

function documentedWebhookParams(callSid) {
  return {
    CallSid: callSid,
    AccountSid: accountSid,
    From: "+14155550100",
    To: "+14155550101",
    CallStatus: "ringing",
    ApiVersion: "2010-04-01",
    Direction: "inbound",
    ForwardedFrom: "+14155550102",
    CallerName: "Carrier Simulator",
    ParentCallSid: makeSid("CA"),
    FromCity: "SAN FRANCISCO",
    FromState: "CA",
    FromZip: "94105",
    FromCountry: "US",
    ToCity: "OAKLAND",
    ToState: "CA",
    ToZip: "94612",
    ToCountry: "US",
  };
}

async function postWebhook(params, signatureOverride) {
  const signature =
    signatureOverride ?? twilio.getExpectedTwilioSignature(authToken, webhookUrl, params);
  if (signatureOverride === undefined) {
    assert.equal(twilio.validateRequest(authToken, signature, webhookUrl, params), true);
  }
  const body = new URLSearchParams(params).toString();
  return new Promise((resolve, reject) => {
    const request = https.request(webhookUrl, {
      method: "POST",
      headers: {
        "content-type": "application/x-www-form-urlencoded",
        "content-length": Buffer.byteLength(body),
        "x-twilio-signature": signature,
      },
      lookup: loopbackLookup,
      rejectUnauthorized: false,
    }, (response) => {
      const chunks = [];
      response.on("data", (chunk) => chunks.push(chunk));
      response.on("end", () => resolve({
        status: response.statusCode,
        text: async () => Buffer.concat(chunks).toString("utf8"),
      }));
    });
    request.once("error", reject);
    request.end(body);
  });
}

function parseStreamUrl(twiml) {
  const encoded = twiml.match(/<Stream\s+url="([^"]+)"/)?.[1];
  return encoded?.replaceAll("&amp;", "&");
}

function openStream(streamUrl) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(streamUrl, {
      lookup: loopbackLookup,
      rejectUnauthorized: false,
    });
    ws.once("open", () => resolve(ws));
    ws.once("error", reject);
  });
}

function waitForClose(ws, timeoutMs = 5000) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("timed out waiting for stream close")), timeoutMs);
    ws.once("close", (code, reason) => {
      clearTimeout(timer);
      resolve({ code, reason: reason.toString() });
    });
  });
}

async function metrics() {
  const response = await fetch(metricsUrl);
  assert.equal(response.status, 200);
  return response.json();
}

function startFrame(callSid, streamSid) {
  return {
    event: "start",
    sequenceNumber: "1",
    start: {
      accountSid,
      streamSid,
      callSid,
      tracks: ["inbound"],
      customParameters: { proof: "carrier-sim-989" },
      mediaFormat: { encoding: "audio/x-mulaw", sampleRate: 8000, channels: 1 },
    },
    streamSid,
  };
}

async function runAllowedPath() {
  const before = await metrics();
  const response = await postWebhook(documentedWebhookParams(matchingCallSid));
  const twiml = await response.text();
  assert.equal(response.status, 200);
  assert.match(twiml, /<Connect>/);
  const streamUrl = parseStreamUrl(twiml);
  assert(streamUrl, "signed webhook did not return a Stream URL");
  log("webhook.accepted", { status: response.status, callSid: redactSid(matchingCallSid) });
  log("stream.url", { url: redactUrl(streamUrl) });

  const ws = await openStream(streamUrl);
  const serverFrames = [];
  ws.on("message", (data) => {
    const frame = JSON.parse(data.toString());
    serverFrames.push(frame);
    log("stream.server-frame", { type: frame.event ?? "unknown" });
  });
  ws.send(JSON.stringify({ event: "connected", protocol: "Call", version: "1.0.0" }));
  const start = startFrame(matchingCallSid, matchingStreamSid);
  ws.send(JSON.stringify(start));
  log("stream.start.sent", {
    frame: { ...start, start: { ...start.start, accountSid: "AC…redacted", streamSid: "MZ…redacted", callSid: "CA…redacted" }, streamSid: "MZ…redacted" },
  });
  for (let index = 0; index < 50; index += 1) {
    ws.send(
      JSON.stringify({
        event: "media",
        sequenceNumber: String(index + 2),
        media: {
          track: "inbound",
          chunk: String(index + 1),
          timestamp: String(index * 20),
          payload: mediaPayload,
        },
        streamSid: matchingStreamSid,
      }),
    );
  }
  await new Promise((resolve) => setTimeout(resolve, 500));
  ws.send(JSON.stringify({ event: "mark", sequenceNumber: "52", mark: { name: "carrier-proof" }, streamSid: matchingStreamSid }));
  ws.send(JSON.stringify({ event: "stop", sequenceNumber: "53", stop: { accountSid, callSid: matchingCallSid }, streamSid: matchingStreamSid }));
  await new Promise((resolve) => setTimeout(resolve, 500));
  if (ws.readyState === WebSocket.OPEN) ws.close(1000, "simulator complete");
  const close = await waitForClose(ws);
  const observed = await metrics();
  const realtimeSessionsAdded = observed.sessions - before.sessions;
  const realtimeAudioFramesAdded = observed.audioFrames - before.audioFrames;
  assert.equal(realtimeSessionsAdded, 1, "matching start did not create exactly one realtime session");
  assert(realtimeAudioFramesAdded >= 50, "media frames did not reach the realtime bridge target");
  assert(serverFrames.some((frame) => frame.event === "media"), "no outbound Twilio media frame received");
  log("allowed.complete", { mediaSent: 50, realtimeSessionsAdded, realtimeAudioFramesAdded, serverFrames: serverFrames.map((frame) => frame.event), close });
}

async function runMismatchPath() {
  const before = await metrics();
  const response = await postWebhook(documentedWebhookParams(mismatchSignedCallSid));
  const streamUrl = parseStreamUrl(await response.text());
  assert.equal(response.status, 200);
  assert(streamUrl);
  const ws = await openStream(streamUrl);
  ws.send(JSON.stringify({ event: "connected", protocol: "Call", version: "1.0.0" }));
  ws.send(JSON.stringify(startFrame(mismatchedCallSid, mismatchStreamSid)));
  const close = await waitForClose(ws);
  const after = await metrics();
  assert.deepEqual(close, { code: 1008, reason: "Call identity does not match stream session" });
  assert.equal(after.sessions, before.sessions, "mismatched start created a realtime session");
  log("mismatch.rejected", { callSid: redactSid(mismatchedCallSid), close, realtimeSessionsAdded: 0 });
}

async function runWebhookNegativePaths() {
  const blankParams = documentedWebhookParams("   ");
  const blankResponse = await postWebhook(blankParams);
  const blankBody = await blankResponse.text();
  assert.equal(blankResponse.status, 200);
  assert.match(blankBody, /<Reject reason="rejected" \/>/);
  assert.doesNotMatch(blankBody, /<Stream/);
  log("blank-call-sid.rejected", { status: blankResponse.status, streamIssued: false });

  const invalidResponse = await postWebhook(documentedWebhookParams(matchingCallSid), "invalid-signature");
  assert.equal(invalidResponse.status, 401);
  log("invalid-signature.rejected", { status: invalidResponse.status });
}

await runAllowedPath();
await runMismatchPath();
await runWebhookNegativePaths();
log("simulator.complete", { result: "PASS" });
```

</details>

## What problem this solves

A delegated system-agent change (config or plugin install, approved by a human or by an "auto-approve changes" grant) re-checked the requesting run's authority at almost every step after the request started:
- after reconciliation;
- when resolving the proposal;
- before applying a non-deny decision;
- at the persistent-effect boundary, including a late re-check of the auto-approve grant;
- before continuing a correction;
- at the decision continuation;
- in a reconciliation poll (`forceDenyIfRuntimeAuthorityClosed`).

If the run ended after a human had already approved, the approved change was silently not applied. The poll was also the last reader of `isExecApprovalRuntimeActive`, kept alive by #201812.

The repo rule (AGENTS.md, "Choose good compromises") is to check authority one time, when work starts. Revocation applies to the next request, and a started request may finish.

## Change

- Run authority is checked once, at request admission. The admission checks stay unchanged.
- Deleted: the run-authority re-checks listed above, the late auto-approve grant re-check at the apply boundary, the reconciliation poll, `forceDenyIfRuntimeAuthorityClosed` and `isExecApprovalRuntimeActive`. Reconciliation retires an unusable proposal with the same `forceDenyDetailed(…, "run-aborted", …, "cancelled")` call the run-closure cancellation already uses. That call is a no-op on missing or already-resolved records: the store returns before writing.
- Kept:
  - admission;
  - session identity and pending-object ownership;
  - proposal-hash reuse;
  - the initial auto-approve grant check (a correction re-enters it, so it gets its own consent);
  - the one-correction bound;
  - the signal listeners.
- Pending approvals of an ended run are still cancelled, by the run-closure observer and the signal listeners.
- A user Stop still refuses the change: at proposal resolution and again at the apply boundary, by checking the request's own abort signals. That is cancellation, not an authority re-check, and it applies in both approval and Full Access mode.
- Accepted edge (commented at the apply callback): a Gateway reload, a worker removal or a revoked source grant after approval applies to the next request. The approved apply finishes. All are still checked at admission.

Known follow-up (separate S1 chain): a config approved by a human before its run ended is now applied, but the outer tool caller still reports a rejection (`src/agents/tools/in-process-gateway.ts:208` through `gateway-caller-context.ts:471`). That is the caller-authority chain, which has its own PR.

## User impact

A change a human approved while the run was live is applied, even if the run ends before the apply finishes. A pending approval for a run that ended is still cancelled, and a user Stop during inference still prevents an automatic change.

## Evidence

Proof tier: source (`ocx test`).

- New: a Full Access inference Stop refuses the proposal and applies nothing. It passes on unchanged `main` too, because it pins kept behavior. Also new: a human-approved change applies after its run ends.
- Run-close-before-decision cases now drive `cancelAgentRuntimeBoundApprovals` (the production observer path) instead of a manual force-deny.
- 33 system-agent and approval test files: 367 tests pass. Expectations that pinned the old refusal were updated to the new contract: `tool-resolution.effects.test-support.ts` (applied config), `system-agent.host-lifecycle.test.ts` (run/Gateway/worker loss after approval completes; Stop still refuses) and `system-agent-owner-write.integration.test.ts` (a revoked source grant after approval persists; non-owner refusal kept).
- `pnpm tsgo`, `pnpm check:test-types`, oxlint, format, and the lifetime-check, line-cap, session-identity, mock-export and max-lines ratchets: pass. `rg isExecApprovalRuntimeActive|forceDenyIfRuntimeAuthorityClosed src` is empty.

Production +24 −74 lines.

issues.body:
**Files:** `container/cli-tools.test.ts`, `.claude/skills/add-vercel/vercel-manifest.test.ts`

`container/cli-tools.test.ts` has:

```ts
it('bakes in nothing that a skill is meant to add on request', () => {
  const names = manifest.map((t) => t.name);
  expect(names).not.toContain('vercel');
});
```

`/add-vercel` installs the CLI by appending `{ "name": "vercel", "version": … }` to the same `container/cli-tools.json`. Its own `vercel-manifest.test.ts` then asserts `expect(names).toContain('vercel')`.

Once the skill is applied, the trunk suite and the skill's suite contradict each other, so `pnpm test` goes red on any install that has `/add-vercel`. The guard is meant to stop vercel being baked in by default. But it can't tell "trunk ships vercel" apart from "the operator installed vercel via the sanctioned skill", because both are the same manifest entry.

**Repro:** run `/add-vercel` on a clean checkout, then `pnpm exec vitest run container/cli-tools.test.ts`.

**Suggested fixes:**
- Run the boundary check against the manifest as shipped on trunk, not the working copy. For example, compare against a baseline list, or mark skill-added entries (`"addedBy": "add-vercel"`) and exclude those.
- Or drop the guard and rely on review. The opt-in boundary is already documented.

## QwenPaw Version

Upstream `main` @ `28f00a679c` (v2.3.0.post1, 2026-11-17). The behavior has been present since `c54a4465` ("fix(console): adapt mobile chat input for safe area and virtual keyboard"), which introduced `viewport-fit=cover`.

**Related issue:** #4738 — that issue fixed the **bottom** safe area only. This report is the missing **top** counterpart.

**Security considerations:** None.

## Component(s) Affected

- [ ] Core / Backend (app, agents, config, providers, utils, local_models)
- [x] Console (frontend web UI)
- [ ] Channels (DingTalk, Feishu, QQ, Discord, iMessage, etc.)
- [ ] Skills
- [ ] CLI
- [ ] Documentation (website)
- [ ] Tests
- [ ] CI/CD
- [ ] Scripts / Deploy

## Description

When the Web Console is opened in a **full-screen container** (a WebView without browser chrome, a PWA installed in `standalone` mode, or an iOS/Android home-screen shortcut), the top of the page is drawn underneath the system status bar / notch. The status bar clock and battery icons overlap the page content, and the first row of UI becomes partially unreadable and untappable.

`console/index.html` declares:

```html
<meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />
```

With `viewport-fit=cover`, the layout viewport is extended into the notch / status bar area, and the page is expected to inset its own content using `env(safe-area-inset-*)`. The console does this for the **bottom** edge but not for the **top** edge.

Verified on upstream `main` today:

```
$ git grep -n "safe-area-inset-top" -- console/
(no matches)

$ git grep -n "safe-area-inset" -- console/
console/src/components/LoopInput/index.module.less:271:  padding: 10px 12px calc(12px + env(safe-area-inset-bottom, 0px));
console/src/components/interaction/BottomSheet.module.less:62:  max(var(--app-space-5), env(safe-area-inset-bottom));
console/src/components/interaction/BottomSheet.module.less:71:  max(var(--app-space-5), env(safe-area-inset-bottom));
console/src/features/project-directory/SessionProjectDirectory.module.less:879: ... env(safe-area-inset-bottom, 0px));
console/src/features/terminal/TerminalDock.module.less:130: ... max(12px, env(safe-area-inset-bottom, 0px));
console/src/layouts/index.module.less:1154:  padding-bottom: max(8px, env(safe-area-inset-bottom));
console/src/os/useOsStyles.ts:1216:  bottom: max(8px, env(safe-area-inset-bottom));
console/src/os/useOsStyles.ts:1531:  bottom: max(8px, env(safe-area-inset-bottom));
console/src/pages/Chat/components/ApprovalToggle.module.less:5: ... env(safe-area-inset-bottom, 0px));
console/src/pages/Chat/index.module.less:411: ... env(safe-area-inset-bottom, 0px)) !important;
console/src/pages/CommunityFeedback/index.module.less:609:  padding: 12px 16px max(12px, env(safe-area-inset-bottom));
console/src/pages/CommunityFeedback/index.module.less:885:  padding: 12px 16px max(12px, env(safe-area-inset-bottom));
console/src/styles/layout.css:892:  padding-bottom: env(safe-area-inset-bottom, 0px) !important;
console/src/styles/layout.css:911:  padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 8px) !important;
```

**17 occurrences, all `-bottom`, zero `-top`.** The top edge is never handled.

Additionally, 15 "mobile adaptation" PRs (#5444, #5446, #5451, #5369, #5384, #5385, #5391, #5397, #5445, #5449, #5458, #5459, #5463, #5464, #5470) adjust layout via responsive breakpoints (`max-width: 768px`) but none of them address safe-area insets. `#5444` ("mobile adaptation for sidebar, header, and page header"), the most relevant one, contains no `safe-area` or `inset-top` at all.

## Steps to Reproduce

1. Deploy the console and open it on a phone **in a full-screen container**, for example:
   - an Android app embedding the console in a `WebView` (`setEdgeToEdgeEnabled`/immersive mode without `WindowInsets` padding), **or**
   - a PWA added to the home screen (`display: standalone`), **or**
   - an Android/iOS home-screen shortcut opening in standalone mode.
2. Observe the top 0–50 px of the page, i.e. `layouts/index.module.less` `.mainLayout` (line 2, `height: 100vh`), which contains `.header` (line 45, `height: 56px`, no top inset) and `.sider` (line 101).
3. Compare with the status bar overlay: the clock and battery icons sit on top of the header content.

Note: the bug is **not** reproducible in a normal mobile browser tab, because the browser chrome occupies the status bar region and `env(safe-area-inset-top)` resolves to `0px` there. It only appears once the browser chrome disappears (WebView / standalone).

## Actual vs Expected

- **Actual:** The page starts at the physical top edge of the screen. `.mainLayout` has `height: 100vh` with no `padding-top`, so the header / sidebar brand is rendered underneath the system status bar and is partially obscured by it.
- **Expected:** The page should reserve `env(safe-area-inset-top)` at the top edge, keeping the background color bleeding behind the status bar (so the notch area is themed) while the interactive content starts below the status bar — consistent with how the 17 existing `-bottom` insets already behave.

## Suggested Fix

Apply the top inset on the root layout container, which fixes every page at once:

```diff
 /* console/src/layouts/index.module.less */
 .mainLayout {
   height: 100vh;
   min-height: 100vh;
   flex-direction: row;
   overflow: hidden;
+  box-sizing: border-box;
+  padding-top: env(safe-area-inset-top, 0px);
+  padding-left: env(safe-area-inset-left, 0px);
+  padding-right: env(safe-area-inset-right, 0px);
 }
```

And the equivalent for the desktop-OS shell (`console/src/os/useOsStyles.ts`), where `MENUBAR_H` is currently a flat 28 px:

```diff
-  height: MENUBAR_H,
+  height: calc(MENUBAR_Hpx + env(safe-area-inset-top, 0px)),
+  paddingTop: "env(safe-area-inset-top, 0px)",
```

The `Login` page (`console/src/pages/Login/index.tsx`) and the full-screen chat view also use `100vh` roots, so the inline `padding` there needs the same treatment:

```diff
-  padding: "24px 16px",
+  padding: "calc(24px + env(safe-area-inset-top, 0px)) 16px calc(24px + env(safe-area-inset-bottom, 0px))",
```

Because `env(safe-area-inset-top)` resolves to `0px` on desktop and in normal browser tabs, these changes are no-ops outside full-screen mobile containers, so they carry no regression risk.

A `100dvh`-based height alongside `100vh` would also be worth adding for the mobile browser toolbar case:

```less
@supports (height: 100dvh) {
  @media (max-width: 768px) {
    .mainLayout { height: 100dvh; min-height: 100dvh; }
  }
}
```

## Logs / Screenshots

Measured from a phone screenshot captured in a full-screen container (device pixel ratio ≈ 3.1, screenshot 1280 × 2781 physical px):

- The first non-background page pixels appear at physical `y ≈ 60 px` (≈ 19 CSS px from the top edge), i.e. **above** the status bar baseline.
- The status bar icon band occupies physical `y ≈ 80–118 px` (clock, battery).
- The page's own top-row elements occupy the same `y ≈ 75–118 px` band, so the two overlap directly.
- Sampled colors in the overlapped region match the console brand logo gradient (`#15D1EE` → `#246BFF`), confirming that it is a page-owned element rather than a browser overlay.

I can attach the raw screenshot as a follow-up comment if that helps — GitHub's REST API cannot upload binary attachments, so this report uses pixel measurements instead.

## Additional Notes

This is a general Web-platform defect of the console, not specific to any downstream customisation. Since `viewport-fit=cover` is opt-in and already enabled, adding the matching top inset completes the intent of #4738 rather than changing the design. Happy to send a PR against `.mainLayout` + `.header` + `useOsStyles.ts` if the maintainers agree with the approach.

prs.body:
---
name: odt
description: "Use this skill whenever the user wants to create, fill, read, or convert OpenDocument Format files (.odt, .ods). Triggers include: any mention of 'ODT', 'ODS', 'ODF', 'OpenDocument', 'LibreOffice document', or requests to produce documents in open-source or ISO standard formats. Also use when converting HTML, Markdown, or TipTap/ProseMirror JSON to ODT, filling ODT templates with data, reading or extracting content from ODT files, generating ODS spreadsheets, reading ODS files, converting XLSX to ODS, converting DOCX to ODT, or creating formal documents like resolutions, reports, letters, contracts, invoices, or memos as .odt files. Use this skill instead of the docx skill when the user explicitly requests .odt output or mentions LibreOffice/OpenOffice as their target application. Do NOT use for .docx files (use the docx skill), PDFs, presentations, or general coding tasks unrelated to document generation."
license: Apache-2.0
---

# odf-kit — OpenDocument Format for JavaScript and TypeScript

## Overview

An `.odt` file is an OpenDocument Format text document — an ISO standard (ISO/IEC 26300) ZIP archive containing XML files. It is the native format for LibreOffice, Apache OpenOffice, Collabora, OnlyOffice, and is supported by Google Docs and Microsoft Office.

odf-kit is the only actively maintained JavaScript/TypeScript library for ODF generation. It produces spec-validated output (validated against the OASIS ODF Validator on every CI run). Works in Node.js 22+ and browsers. No LibreOffice dependency.

## Quick Reference

| Task | Import | Function |
|------|--------|----------|
| Create new ODT document | `"odf-kit"` | `new OdtDocument()` |
| Fill existing ODT template | `"odf-kit"` | `fillTemplate(bytes, data)` |
| HTML → ODT | `"odf-kit"` | `htmlToOdt(html, options?)` |
| Markdown → ODT | `"odf-kit"` | `markdownToOdt(markdown, options?)` |
| TipTap/ProseMirror JSON → ODT | `"odf-kit"` | `tiptapToOdt(json, options?)` |
| Build ODS spreadsheet | `"odf-kit"` | `new OdsDocument()` |
| Read ODT / convert to HTML | `"odf-kit/reader"` | `readOdt(bytes)` / `odtToHtml(bytes)` |
| Read ODS | `"odf-kit/ods-reader"` | `readOds(bytes)` / `odsToHtml(bytes)` |
| XLSX → ODS | `"odf-kit/xlsx"` | `xlsxToOds(bytes)` |
| DOCX → ODT | `"odf-kit/docx"` | `docxToOdt(bytes, options?)` |
| ODT → Typst / PDF | `"odf-kit/typst"` | `odtToTypst(bytes)` |

### Installation

```bash
npm install odf-kit
```

Requires Node.js 22 or later. ESM only.

---

## Creating New ODT Documents

Generate .odt files with JavaScript using odf-kit's builder API.

### Setup

```javascript
import { OdtDocument } from "odf-kit";
import { writeFileSync } from "fs";

const doc = new OdtDocument();
doc.addHeading("Document Title", 1);
doc.addParagraph("Body text goes here.");

const bytes = await doc.save();
writeFileSync("output.odt", bytes);
```

### Metadata

```javascript
doc.setMetadata({
  title: "Quarterly Report",
  creator: "Jane Doe",
  description: "Q4 2026 financial summary",
});
```

### Page Layout

```javascript
doc.setPageLayout({
  orientation: "landscape",       // or "portrait" (default)
  width: "21cm",                  // default A4
  height: "29.7cm",
  marginTop: "2cm",
  marginBottom: "2cm",
  marginLeft: "2cm",
  marginRight: "2cm",
});
```

**For US Letter:** Use `width: "8.5in"` and `height: "11in"`.

### Headers and Footers

```javascript
// Simple string (### = page number)
doc.setHeader("Confidential — Page ###");
doc.setFooter("© 2026 Acme Corp — Page ###");

// Builder for formatted headers
doc.setHeader((h) => {
  h.addText("Confidential", { bold: true, color: "gray" });
  h.addText(" — Page ");
  h.addPageNumber();
});
```

### Headings

```javascript
// Basic heading (levels 1–6)
doc.addHeading("Chapter Title", 1);
doc.addHeading("Section Title", 2);

// With paragraph options
doc.addHeading("Centered Title", 1, { align: "center" });
doc.addHeading("Title with Space", 1, { spaceBefore: "0.5cm", spaceAfter: "0.5cm" });
```

### Paragraphs

```javascript
// Plain text
doc.addParagraph("Simple paragraph.");

// With paragraph options
doc.addParagraph("Right-aligned text.", { align: "right" });

// Builder for mixed formatting
doc.addParagraph((p) => {
  p.addText("Normal and ");
  p.addText("bold", { bold: true });
  p.addText(" text.");
});

// Builder with paragraph options
doc.addParagraph((p) => {
  p.addText("Indented paragraph content.");
}, { indentLeft: "1cm", indentFirst: "0.5cm" });
```

**Paragraph options:**

| Option | Type | Example | Description |
|--------|------|---------|-------------|
| `align` | string | `"left"`, `"center"`, `"right"`, `"justify"` | Text alignment |
| `spaceBefore` | string | `"0.5cm"` | Space above paragraph |
| `spaceAfter` | string | `"0.5cm"` | Space below paragraph |
| `lineHeight` | number or string | `1.5` or `"150%"` | Line spacing (number = multiplier) |
| `indentLeft` | string | `"1cm"` | Left indent |
| `indentRight` | string | `"1cm"` | Right indent |
| `indentFirst` | string | `"0.5cm"` | First-line indent (positive) or hanging indent (negative) |
| `tabStops` | array | `[{ position: "6cm", type: "right" }]` | Tab stop positions |

### Text Formatting

```javascript
doc.addParagraph((p) => {
  p.addText("Bold", { bold: true });
  p.addText("Italic", { italic: true });
  p.addText("Underline", { underline: true });
  p.addText("Strikethrough", { strikethrough: true });
  p.addText("Super", { superscript: true });
  p.addText("Sub", { subscript: true });
  p.addText("Arial 14pt red", { fontFamily: "Arial", fontSize: 14, color: "#CC0000" });
  p.addText("Highlighted", { highlightColor: "#FFFF00" });
  p.addText("UPPERCASE", { textTransform: "uppercase" });
  p.addText("Small Caps", { smallCaps: true });
  p.addText("Weight 300", { fontWeight: 300 });   // numeric 100–900
  p.addText("Weight bold", { fontWeight: "bold" });
});
```

**All text formatting options:**

| Option | Type | Example |
|--------|------|---------|
| `bold` | boolean | `true` |
| `italic` | boolean | `true` |
| `underline` | boolean | `true` |
| `strikethrough` | boolean | `true` |
| `superscript` | boolean | `true` |
| `subscript` | boolean | `true` |
| `fontSize` | number or string | `14` or `"14pt"` |
| `fontFamily` | string | `"Arial"` |
| `fontWeight` | string or number | `"bold"`, `300`, `700` |
| `fontStyle` | string | `"normal"`, `"italic"` |
| `color` | string | `"#FF0000"` or `"red"` |
| `highlightColor` | string | `"#FFFF00"` or `"yellow"` |
| `textTransform` | string | `"uppercase"`, `"lowercase"`, `"capitalize"` |
| `smallCaps` | boolean | `true` |

### Tables

```javascript
// Simple — array of arrays
doc.addTable([
  ["Name", "Role", "Department"],
  ["Alice", "Engineer", "R&D"],
  ["Bob", "Designer", "UX"],
]);

// With options
doc.addTable([
  ["Item", "Price"],
  ["Widget", "$9.99"],
], { columnWidths: ["8cm", "4cm"], border: "0.5pt solid #000000" });

// Full control — builder callback
doc.addTable((t) => {
  t.addRow((r) => {
    r.addCell("Header", {
      bold: true,
      backgroundColor: "#DDDDDD",
      verticalAlign: "middle",
      padding: "0.15cm",
    });
    r.addCell("Value", {
      bold: true,
      backgroundColor: "#DDDDDD",
      colSpan: 2,
    });
  }, { backgroundColor: "#DDDDDD" });

  t.addRow((r) => {
    r.addCell("Status");
    r.addCell("Complete", { color: "green" });
    r.addCell("Verified", { border: "0.5pt solid #000000" });
  });

  // Row spanning
  t.addRow((r) => {
    r.addCell("Tall", { rowSpan: 2, verticalAlign: "top" });
    r.addCell("Normal");
  });
  t.addRow((r) => {
    r.addCell("Adjacent to rowspan");
  });
}, { columnWidths: ["4cm", "4cm", "4cm"] });
```

**Cell options** (extends all text formatting options, plus):

| Option | Type | Example |
|--------|------|---------|
| `backgroundColor` | string | `"#EEEEEE"` |
| `border` | string | `"0.5pt solid #000000"` |
| `borderTop` / `borderBottom` / `borderLeft` / `borderRight` | string | Per-side borders |
| `colSpan` | number | `2` |
| `rowSpan` | number | `3` |
| `verticalAlign` | string | `"top"`, `"middle"`, `"bottom"` |
| `padding` | string | `"0.15cm"` |

### Lists

```javascript
// Simple bullet list
doc.addList(["Apples", "Bananas", "Cherries"]);

// Numbered list
doc.addList(["First", "Second", "Third"], { type: "numbered" });

// Alpha / roman / custom formats
doc.addList(["Item a", "Item b"], { type: "numbered", numFormat: "a" });
doc.addList(["Item A", "Item B"], { type: "numbered", numFormat: "A" });
doc.addList(["Item i", "Item ii"], { type: "numbered", numFormat: "i" });
doc.addList(["Step 5", "Step 6"], { type: "numbered", startValue: 5 });
doc.addList(["Item", "Item"], { type: "numbered", numPrefix: "(", numSuffix: ")" });

// Nested with formatting — builder callback
doc.addList((l) => {
  l.addItem((p) => {
    p.addText("Important: ", { bold: true });
    p.addText("read the documentation");
  });
  l.addItem("Main topic");
  l.addNested((sub) => {
    sub.addItem("Subtopic A");
    sub.addItem("Subtopic B");
  });
});
```

**List options:**

| Option | Type | Example | Description |
|--------|------|---------|-------------|
| `type` | string | `"numbered"` | `"bullet"` (default) or `"numbered"` |
| `numFormat` | string | `"a"`, `"A"`, `"i"`, `"I"` | Number format; default `"1"` |
| `numPrefix` | string | `"("` | Text before number |
| `numSuffix` | string | `")"` | Text after number; default `"."` |
| `startValue` | number | `5` | Starting number |

### Images

```javascript
import { readFile } from "fs/promises";
const logo = await readFile("logo.png");

// Standalone
doc.addImage(logo, { width: "10cm", height: "6cm", mimeType: "image/png" });

// Inline in text
doc.addParagraph((p) => {
  p.addText("Logo: ");
  p.addImage(logo, { width: "2cm", height: "1cm", mimeType: "image/png" });
});
```

**Image options:**

| Option | Type | Required | Description |
|--------|------|----------|-------------|
| `width` | string | Yes | `"10cm"`, `"4in"` |
| `height` | string | Yes | `"6cm"`, `"3in"` |
| `mimeType` | string | Yes | `"image/png"`, `"image/jpeg"` |
| `anchor` | string | No | `"as-character"` or `"paragraph"` |

### Links and Bookmarks

```javascript
// External URL
doc.addParagraph((p) => {
  p.addText("Visit ");
  p.addLink("our website", "https://example.com", { bold: true });
});

// Internal bookmark target
doc.addParagraph((p) => {
  p.addBookmark("section-one");
  p.addText("Section 1: Introduction");
});

// Link to internal bookmark
doc.addParagraph((p) => {
  p.addLink("Go to Section 1", "#section-one");
});
```

### Tab Stops

```javascript
doc.addParagraph((p) => {
  p.addText("Item");
  p.addTab();
  p.addText("Qty");
  p.addTab();
  p.addText("$100.00");
}, {
  tabStops: [
    { position: "6cm" },
    { position: "12cm", type: "right" },
  ],
});
```

### Page Breaks

```javascript
doc.addPageBreak();
```

### Method Chaining

Every method returns the document for chaining:

```javascript
const bytes = await new OdtDocument()
  .setMetadata({ title: "Report" })
  .setPageLayout({ orientation: "landscape" })
  .setHeader("Confidential")
  .setFooter("Page ###")
  .addHeading("Summary", 1)
  .addParagraph("All systems operational.")
  .addTable([["System", "Status"], ["API", "OK"], ["DB", "OK"]])
  .addList(["No incidents", "No alerts"], { type: "numbered" })
  .save();
```

